import java.util.Scanner;
public class JWinPercentageInput {
	public static void main(String[] args) {
		//Paso 1: Leer el numero de juegos en el torneo
		Scanner scan = new Scanner(System.in);
		System.out.println("Ingrese el numero de juegos en el torneo: ");
		int totalGames = scan.nextInt();		
		//Paso 2: Validar la entrada del usuario para el numero de juegos en el torneo, pedir una entrada valida mientras el usuario introduzca un numero invalido; de lo contrario detenerse
		while ( totalGames <= 0 ) {
			System.out.println("Ingrese el numero de juegos en el torneo: ");
			totalGames = scan.nextInt();
		}
		//Paso 3: Leer el numero de juegos que el equipo deportivo gano en el torneo
		System.out.println("Ingrese el numero de juegos que el equipo deportivo gano en el torneo: ");
		int wins = scan.nextInt();		
		//Paso 4: Validar la entrada del usuario para el numero de juegos que el equipo deportivo gano en el torneo, pedir una entrada valida mientras el usuario introduzca un numero invalido; de lo contrario detenerse
		while ( wins < 0 || wins > totalGames ) {
			System.out.println("Ingrese el numero de juegos que el equipo deportivo gano en el torneo: ");
			wins = scan.nextInt();
		}
		scan.close();
		//Paso 5: Calcular e imprimir el porcentaje de juegos ganados por un equipo
		double ratio = (double) wins / totalGames;
		DecimalFormat fmt = new DecimalFormat("0.###");
		System.out.println("Porcentaje de victorias:" + fmt.format(ratio));
	}
}

